export function FavoritesProvider({
  children,
  initial,
  /**
   * Whether there is a session to save against. On the sign-in, sign-up and
   * standalone-legal screens there is not, and no request should be made —
   * none of those screens shows a star, so this only guards the impossible.
   */
  signedIn,
}: {
  children: React.ReactNode;
  initial: string[];
  signedIn: boolean;
}) {
  const [favorites, setFavorites] = useState<string[]>(initial);

  /**
   * The same list, readable synchronously.
   *
   * `toggle` has to know what is starred *now* to decide what to send and what
   * to roll back to, and it cannot get that from the `favorites` binding: two
   * clicks in the same tick both close over the value from the render that
   * created them, so the second would compute its next list from one that is
   * already stale.
   *
   * Deliberately not done by reading the value inside a `setFavorites`
   * updater either. React evaluates an updater immediately only while that
   * hook's queue is empty; a click landing during a pending update gets
   * deferred instead, and anything the updater was meant to hand back to the
   * caller is still undefined on the next line. That is what this file did
   * before, and the symptom was a star that lit up and was never saved.
  if ("response" in auth) return auth.response;
  const account = auth.account;

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return Response.json({ error: "Expected a JSON object." }, { status: 400 });
  }

  const { slug, favorite } = (body ?? {}) as {
    slug?: unknown;
    favorite?: unknown;
  };

  // Checked against the catalog, not merely for being a string: this value is
  // going into the user's row, and an unbounded one would make that row a
  // place to park arbitrary text.
  if (typeof slug !== "string" || !findSkill(slug)) {
    return Response.json({ error: "Unknown skill." }, { status: 400 });
  }
  if (typeof favorite !== "boolean") {
    return Response.json(
      { error: "body.favorite must be a boolean." },
      { status: 400 },
    );
  }

  try {
    const updated = await (await users()).findOneAndUpdate(
      { _id: new ObjectId(account.id) },
      favorite
        ? { $addToSet: { favorites: slug } }
        : { $pull: { favorites: slug } },
      { returnDocument: "after" },
    );
    if (!updated) {
      return Response.json({ error: "Not signed in." }, { status: 401 });
    }
    return Response.json({ favorites: updated.favorites ?? [] });
  } catch (err) {
    return Response.json(
      { error: `Could not reach the user store: ${(err as Error).message}` },
      { status: 503 },
    );
  }
  // this checks that it still resolves to a user before rendering.
  await requireAccount();
  const skill = findSkill((await params).slug);
  if (!skill) notFound();
  const { locale, t: messages } = await readMessages();
  const t = messages.skillPage;
  const shown = skillDisplay(locale, skill);

  // `?autorun=1&context=...` is a run the dashboard's Reconnect is sending
  // here, with what it found. Read on the server so the form mounts already
  // knowing, rather than mounting empty and then noticing. See `SkillForm`.
  const query = await searchParams;
  const context = typeof query.context === "string" ? query.context : "";
  // `autorun` carries a one-time token that Reconnect also left in this tab's
  // sessionStorage; `SkillForm` starts only when the two match, so a link from
  // another site cannot start a run (security audit 2026-11-03).
  const autorun =
    typeof query.autorun === "string" && /^[A-Za-z0-9-]{16,64}$/.test(query.autorun) && skill.status === "ready"
      ? { context: context.slice(0, 2000), token: query.autorun }
      : null;

    // module one at a time and writes .sc4sap/cbo/<MODULE>/<PACKAGE>/; here
    // the three are form fields and the files go to the run's own folder, to
    // be shown and downloaded like a spec's — nothing is kept on the server.
    // Measured 2026-10-04 on ZMMPAEK (362 objects, flagship ZMMR00020), after
    // the app scripts took over the object list and the object table: Economy
    // 190 s, $0.95; Standard 437 s, $1.63 with every section of the stocker's
    // analysis kept; no dialogs (before: 255 s / $1.56 and 466 s / $2.39).
    slug: "analyze-cbo-obj",
    command: "/sc4sap:analyze-cbo-obj",
    tools: "build",
    title: "Inventory a CBO Package",
    icon: "package",
    summary:
      "Walks a custom package and catalogs the Z objects worth reusing, so later runs prefer existing elements over new ones",
    group: "analyze",
    status: "ready",
    fields: [
      { label: "Package", kind: "text", placeholder: "ZMM_CBO", span: "half" },
      {
        label: "Flagship programs",
        kind: "text",
        placeholder: "ZPROGRAM1, ZPROGRAM2",
        hint: "Optional. The programs used most; what they use is pinned to the top.",
        span: "half",
      },
      {
        label: "Mode",
        kind: "select",
        span: "third",
        options: ["Economy", "Standard"],
        optionHints: {
          Economy:
            "One agent walks the package and its where-used graph and describes the objects that matter. Estimated cost: about $0.80–1.20. Estimated time: 2–4 min.",
          Standard:
            "The plugin's skill with its stocker agent; it flags sensitive objects more thoroughly. Estimated cost: about $1.40–2.00. Estimated time: 6–8 min.",
        },
      },
      { label: "Module", kind: "select", options: MODULES.slice(1), span: "third" },
      { label: "Language", kind: "select", options: ["Korean", "English", "Japanese"], span: "third" },
    ],
    documents: "cbo",
  },
  {
    // Built out on 2026-10-12, as the other document skills: the plugin's
    // intake and its scope stop become form fields, the files go to the run's
    // own folder to be shown and downloaded. The mode is the spending
  "/graph": "graph",
  "/monitor": "monitor",
};

/** The guide for a route, or `null` for a screen that has none. */
export function guideFor(pathname: string): GuidePage | null {
  const base = pathname === "/" ? "/" : `/${pathname.split("/")[1] ?? ""}`;
  if (FIXED[base]) return { key: KEYS[base], ...FIXED[base] };
  const skill = /^\/skills\/([a-z0-9-]+)\/?$/.exec(pathname)?.[1];
  if (skill && findSkill(skill)) {
    const steps = skill === "create-program" || skill === "create-object" ? SKILL_CREATE : SKILL;
    return { key: `skill.${skill}`, steps };
  }
  return null;
}

