const map={"ask-consultant":"consultant","analyze-code":"developer","analyze-symptom":"developer","analyze-cbo-obj":"developer","compare-programs":"consultant","program-to-spec":"consultant","program-to-manual":"consultant","module-to-process":"consultant","create-program":"developer","create-object":"developer","sap-doctor":"system"};
let n=0;
s=s.replace(/slug: "([a-z-]+)",([\s\S]*?)group: "(analyze|build|system)",/g,(m,slug,mid,g)=>{n++;if(!map[slug])throw new Error(slug);return `slug: "${slug}",${mid}group: "${map[slug]}",`;});
