/**
 * Slugs a skill used to have. Bookmarks, starred skills saved in the user's
 * row and guide notices still carry them; they resolve to the skill's
 * current slug, and the page redirects there.
 */
export const LEGACY_SLUGS: Record<string, string> = {
  "analyze-cbo-obj": "stock-cbo",
};

/** The current slug for `slug`, old or new. */
export function canonicalSlug(slug: string): string {
  return Object.hasOwn(LEGACY_SLUGS, slug) ? LEGACY_SLUGS[slug] : slug;
}

export function findSkill(slug: string): Skill | undefined {
  const current = canonicalSlug(slug);
  return SKILLS.find((skill) => skill.slug === current);
}

