toolUseResult.originalFile:
/**
 * Which screens have a page guide, and what each step points at.
 *
 * The words live in `lib/i18n/guide.ts`, keyed by the same page key and step
 * id; this file is only the shape: the order of the steps and the element
 * each one highlights. A step whose `target` is missing or not on screen is
 * shown as a centred card instead (see `PageGuide`), so a selector that
 * stops matching degrades the guide rather than breaking it — but keep these
 * in step with the class names they quote.
 *
 * Not guided, on purpose: settings, billing, the legal pages, setup and the
 * dialogs (feedback and the like). They are either one form with its own
 * labels or not part of the work the app is for.
 */
import { findSkill } from "@/lib/skills";

export type GuideStep = {
  id: string;
  target?: string;
  /**
   * Something the step points at that only shows on hover. Set as
   * `data-guide-reveal` on <html> while the step is up; globals.css keeps the
   * thing visible under it.
   */
  reveal?: "fav";
  /**
   * Highlight the box around every visible match of `target` rather than
   * the first — a group of form fields with no element of its own.
   */
  union?: boolean;
  /** A small looping illustration drawn under the step's words. */
  demo?: "fav";
  /** Only in this version of the page's guide (see `GuidePage.ready`). */
  show?: GuideVariant;
  /** Only when this is on screen as the guide opens. `a || b` as for `target`. */
  when?: string;
  /** Only when this is not on screen as the guide opens. */
  unless?: string;
};

/**
 * `ready` — the page has data to walk through (the graph, the call log).
 * `empty` — it has none yet, and the guide says how to get some.
 */
export type GuideVariant = "ready" | "empty";

export type GuidePage = {
  key: string;
  steps: GuideStep[];
  /**
   * On screen once the page has data. Pages without it have one version.
   * With it, the guide waits for the data and picks `ready` or `empty`, and
   * each version is closed for good on its own: the short empty one does
   * not use up the full one.
   */
  ready?: string;
  /** On screen when the page has loaded and has no data. */
  empty?: string;
};

/** Closed for good on every page. A `seenNotices` id like any other. */
export const GUIDE_ALL_OFF = "guide.all-off";

/** Fired by the account menu's "Guide for this page". */
export const GUIDE_OPEN_EVENT = "sc4sap:guide-open";

