import { findSkill } from "@/lib/skills";

export type GuideStep = {
  id: string;
  target?: string;
  /**
   * Something the step points at that only shows on hover. Set as
   * `data-guide-reveal` on <html> while the step is up; globals.css keeps the
   * thing visible under it.
   */
  reveal?: "fav";
  /**
   * Highlight the box around every visible match of `target` rather than
   * the first — a group of form fields with no element of its own.
   */
  union?: boolean;
  /** A small looping illustration drawn under the step's words. */
  demo?: "fav";
  /** Only in this version of the page's guide (see `GuidePage.ready`). */
  show?: GuideVariant;
  /** Only when this is on screen as the guide opens. `a || b` as for `target`. */
  when?: string;
  /** Only when this is not on screen as the guide opens. */
  unless?: string;
};

/**
 * `ready` — the page has data to walk through (the graph, the call log).
 * `empty` — it has none yet, and the guide says how to get some.
 */
export type GuideVariant = "ready" | "empty";

export type GuidePage = {
  key: string;
  steps: GuideStep[];
  /**
   * On screen once the page has data. Pages without it have one version.
   * With it, the guide waits for the data and picks `ready` or `empty`, and
   * each version is closed for good on its own: the short empty one does
   * not use up the full one.
   */
