// and every "Analyze -> ..." menu path in lib/i18n/guide.ts. Exact substrings;
// throws on any miss so nothing is half-applied.
const fs = require("fs");
const p = process.argv[2];
let s = fs.readFileSync(p, "utf8");
const eol = s.includes("\r\n") ? "\r\n" : "\n";
const rep = (a, b, count = 1) => {
  const a2 = a.replace(/\n/g, eol), b2 = b.replace(/\n/g, eol);
  const n = s.split(a2).length - 1;
  if (n !== count) throw new Error(`expected ${count}, found ${n}: ${a.slice(0, 60)}`);
  s = s.split(a2).join(b2);
};

