export function planRun(request: RunRequest): RunPlan | string {
  const skill = findSkill(line(request.slug, 64));
  if (!skill || skill.status !== "ready") return "unknown skill";
  const locale: Locale = request.locale === "ko" || request.locale === "ja" ? request.locale : "en";
  const values: Record<string, Value> = {};
  const given = (request.values ?? {}) as Record<string, unknown>;
  for (const field of skill.fields) {
    const value = given[field.label];
    if (typeof value === "boolean") values[field.label] = value;
    else if (typeof value === "string") values[field.label] = value.slice(0, MAX_TEXT);
  }
  const base = { profile: skill.tools, kind: "task" as const };
  const economyRun = { effort: "medium" as const, solo: true };

  const s = request.system;
  const system: CreateSurvey["system"] =
    s && typeof s === "object"
      ? { version: line(s.version, 80), release: line(s.release, 40), language: line(s.language, 8), user: line(s.user, 40) }
      : null;

  if (skill.slug === "create-object") {
    const survey: ObjectSurvey = { ...objectOf(values), system };
    if (survey.package === "") return "package is required";
    // Ceilings as Create Program's (user, 2026-10-26): $4 Economy, $10
    // Standard, both on Sonnet; Standard's executor is the plugin's Opus.
    return {
      session: {
        ...base,
        model: SONNET,
        economy: survey.method === "Economy",
        maxBudgetUsd: survey.method === "Precise" ? 30 : 5,
        ...(survey.method === "Economy" ? economyRun : {}),
        writeScope: { package: survey.package, transport: survey.transport },
      },
      prompt: (outDir) => objectPrompt(survey, outDir),
    };
  }

  if (skill.slug === "create-program") {
    const survey: CreateSurvey = { ...createOf(values), system };
    if (survey.package === "" || survey.requirement === "") return "package and requirement are required";
    // Both modes on Sonnet. Economy is this app's own one-agent build
    // (`economyPrompt`); Standard is the plugin's skill as written. Ceilings decided by the user on 2026-10-17: Economy was $2
    // and stopped right after spec approval (the SDK's own figure, which
    // prices Sonnet 5 at 1.5x list, was $2.36 there), so it became $4.
    // Raised by the user on 2026-11-03 to $5 Economy / $30 Standard, for
    // Create Object too.
    return {
      session: {
        ...base,
        model: SONNET,
        economy: survey.method === "Economy",
        maxBudgetUsd: survey.method === "Precise" ? 30 : 5,
        // Economy is one agent with its conventions in the prompt: no
        // sub-agent or skill in its context (`solo`), and less thinking.
        ...(survey.method === "Economy" ? economyRun : {}),
        writeScope: { package: survey.package, transport: survey.transport },
      },
      prompt: (outDir) => createPrompt(survey, outDir),
    };
  }

  switch (skill.documents) {
    case "review": {
      const survey = reviewOf(values, locale);
      if (survey.objectName === "") return "object name is required";
      // Economy: one agent on Sonnet, the reviewer's rule files in front of
      // its prompt (`reviewRules`), no sub-agents and no skill to load.
      // Standard: the plugin's skill, on what the cost dialog chose.
      return {
        session: {
          ...base,
          ...(survey.method === "Economy"
            ? { model: SONNET, reviewRules: true, maxBudgetUsd: 1.5 }
            : spendOf(skill, request.how)),
          ...(skill.effort ? { effort: skill.effort } : {}),
        },
        prompt: (outDir) => reviewPrompt(survey, outDir),
      };
    }
    case "compare": {
      const survey = compareOf(values);
      if (survey.programs.length < 2 || survey.programs.length > 5) return "two to five programs are required";
      // Both modes on Sonnet with sub-agents kept off Opus, as the other
      // document skills. Ceilings about three times what ZMMR00020 vs
      // ZMMR00030 measured by the SDK: $0.46 Economy, $1.99 Standard — a
      // run of five programs dispatches five reviewers.
      return {
        session: {
          ...base,
          model: SONNET,
          economy: true,
          maxBudgetUsd: survey.method === "Precise" ? 6 : 1.5,
          ...(survey.method === "Economy" ? economyRun : {}),
        },
        prompt: (outDir) => comparePrompt(survey, outDir),
      };
    }
    case "process": {
      const survey = processOf(values);
      if (survey.packages.length === 0 && survey.tcodes.length === 0) return "a package or a Z TCode is required";
      // Standard measured 45 min and ≈ $8.4 list on ZMMPAEK (2026-10-31),
      // before the heredoc fix took the retyped task sheets out; Eco is not
      // measured yet. Neither asks anything (`noQuestions`).
      return {
        session: {
          ...base,
          model: SONNET,
          economy: true,
          maxBudgetUsd: survey.method === "Precise" ? 15 : 5,
          noQuestions: true,
          ...(survey.method === "Economy" ? economyRun : {}),
        },
        prompt: (outDir) => processPrompt(survey, outDir),
      };
    }
    case "cbo": {
      const survey = cboOf(values);
      if (survey.package === "") return "package is required";
      // No ceiling, as on Program → Spec: this page has nowhere to set one.
      // ZMMPAEK (362 objects) measured $0.95 Economy, $1.63 Standard.
      return {
        session: { ...base, model: SONNET, economy: true, ...(survey.method === "Economy" ? economyRun : {}) },
        prompt: (outDir) => cboPrompt(survey, outDir),
      };
    }
    case "manual": {
      if (programOf(values) === "") return "program name is required";
      const c = request.cover;
      const survey = manualOf(values, {
        author: line(c?.author),
        team: line(c?.team),
        company: line(c?.company),
        confidentiality: line(c?.confidentiality),
      });
      return {
        session: { ...base, model: SONNET, economy: true, ...(survey.method === "Economy" ? economyRun : {}) },
        prompt: (outDir) => manualPrompt(survey, outDir),
      };
    }
    case "spec": {
      if (programOf(values) === "") return "program name is required";
      const a = request.answers;
      const answers =
        a && (a.depth === "Detailed" || a.depth === "Summary") &&
        (a.audience === "Both" || a.audience === "Functional" || a.audience === "Technical")
          ? { depth: a.depth, audience: a.audience }
          : undefined;
      const survey = surveyOf(values, locale, answers);
      // The method is the spending decision here, so there is no cost
      // dialog, and no ceiling either — a ceiling the reader never chose
      // only stops a run half-way with its cost already spent (2026-09-30).
      // Standard keeps the default effort: medium cut its time by about
      // 40% but the reader judged the spec it wrote too thin (2026-10-02).
      return {
        session: { ...base, model: SONNET, economy: true, ...(survey.method === "Economy" ? economyRun : {}) },
        prompt: (outDir) => specPrompt(survey, outDir),
      };
    }
    default: {
      const context = typeof request.context === "string" ? request.context.slice(0, MAX_TEXT) : null;
      return {
        session: {
          ...base,
          ...spendOf(skill, request.how),
          ...(skill.effort ? { effort: skill.effort } : {}),
        },
        prompt: () => composePrompt(skill.command, skill.fields, values, context, locale),
      };
    }
  }
}

