export function takeRunFiles(workspace: string, sessionId: string): RunFile[] {
  const dir = absolute(workspace, sessionId);
  if (!dir || !existsSync(dir)) return [];
  const files: RunFile[] = [];
  try {
    for (const path of walk(dir)) {
      const parts = path.split("/");
