  // judged; a `$` left over after that — a name this did not see set — is a no.
  const names = new Map<string, string>();
  return (
    steps.length > 0 &&
    steps.every((step) => {
      const set = /^([A-Za-z_]\w*)=(?:"([^"$`\\\n]*)"|'([^'\n]*)'|([^\s"'$`;&|<>\\]*))$/.exec(step.trim());
