/**
 * Read-class tools that match no prefix rule at all.
 *
 * Exact names, never a prefix: a later `Validate…` that changes something
 * must not be swept in by a pattern that was written for this one.
 */
const NAMED_READ: ReadonlySet<string> = new Set(["ValidateServiceBinding"]);

/**
 * The agent's own tools that are auto-approved.
 *
 * Not SAP tools at all — these are the SDK's, and they are the reason a single
 * skill run was raising dozens of prompts. `analyze-code` reads nine rule
 * files, keeps a todo list and dispatches a reviewer sub-agent before it has
 * touched the SAP system once, and every one of those was landing in the
 * approval queue as an unclassified `other`. A prompt that fires that often
 * stops being read, which makes the prompts that matter — a write, a table
 * dump — cost nothing to wave through.
 *
 * What is on this list can look at things: the local filesystem the server
 * already gave the session as its `cwd` and plugin path, the model's own
 * bookkeeping, and dispatching work to a sub-agent — whose tool calls come
 * back through this same policy rather than around it.
 *
 * What is deliberately NOT on it, and prompts every time:
 *
 *   Bash, Write, Edit, NotebookEdit — change the machine the server runs on.
 *   WebFetch, WebSearch           — leave the machine entirely.
 *   Every SAP write tool          — not reachable at all; see
 *                                   `disallowedTools` above.
 *
 * Leaving them off this list is necessary and was not sufficient. Built-in
 * tools never reached `canUseTool` at all, so for a while these ran without
 * being asked about — measured, not inferred. What actually stops them is the
 * PreToolUse hook in `session-manager.ts`; see `needsHookApproval` below.
 */
export const MAX_ROWS_PER_READ = 100;

/**
 * The same call with its row count brought under the cap, or the input
 * untouched when it was already inside it.
 *
 * Clamped rather than refused: a refusal costs a round trip and teaches
 * nothing the model could not see from the result, while a capped read still
 * answers the question most of the time. The system prompt says what the cap
 * is, so a short result reads as a limit rather than as an empty table.
 */
export function capRows(
  toolName: string,
  input: Record<string, unknown>,
): Record<string, unknown> {
  const bare = toolName.startsWith(SAP_TOOL_PREFIX)
    ? toolName.slice(SAP_TOOL_PREFIX.length)
    : toolName;
  if (!NEVER_AUTO_ALLOW.has(bare)) return input;

  const field = "max_rows" in input ? "max_rows" : "row_number" in input ? "row_number" : null;
  // No cap named at all: the server applies its own default, which may be
  // larger than ours, so one is named here.
  if (!field) {
    return { ...input, max_rows: MAX_ROWS_PER_READ };
  }
  const asked = input[field];
  if (typeof asked === "number" && Number.isFinite(asked) && asked <= MAX_ROWS_PER_READ) {
    return input;
  }
  return { ...input, [field]: MAX_ROWS_PER_READ };
}

export function rowScope(
  toolName: string,
  input: Record<string, unknown>,
): { key: string; rows: number } | null {
  const bare = toolName.startsWith(SAP_TOOL_PREFIX)
    ? toolName.slice(SAP_TOOL_PREFIX.length)
    : toolName;
  if (!NEVER_AUTO_ALLOW.has(bare)) return null;

  const table =
    typeof input.table_name === "string" && input.table_name.trim() !== ""
      ? input.table_name.trim().toUpperCase()
      : typeof input.sql_query === "string"
        ? (/\bFROM\s+([A-Za-z_][A-Za-z0-9_/]*)/i.exec(input.sql_query)?.[1] ??
            input.sql_query)
            .trim()
            .toUpperCase()
        : "";
  if (table === "") return null;

  // Whichever of the two row caps this tool uses. Absent means the server's
  // own default, which is not zero — treated as unbounded so a call with no
  // cap never rides in on the back of one that named a small number.
  const asked = input.max_rows ?? input.row_number;
  const rows =
    typeof asked === "number" && Number.isFinite(asked) && asked > 0
      ? asked
      : Number.POSITIVE_INFINITY;

  return { key: `${bare}:${table}`, rows };
}

export type ToolClass = "write" | "row-extraction" | "read" | "other";
export function allowedByLevel(
  level: ApprovalLevel,
  toolName: string,
  input: Record<string, unknown>,
  /** The folders a reading `node -e` may name: the workspace and the plugin. Without them it may name none. */
  roots: readonly string[] = [],
): boolean {
  if (toolName === QUESTION_TOOL) return false;
  if (level === "all") return false;
  if (level === "never") return true;
  if (toolName.startsWith(SAP_TOOL_PREFIX)) {
    // Row extraction is a read too (decided 2026-10-17: every read goes
    // through under `writes`). The tables it may touch are still the
    // plugin's blocklist hook's and the MCP server's call, and the session
    // caps the rows (`capRows`) before it lets one through.
    const cls = classifySapTool(toolName.slice(SAP_TOOL_PREFIX.length));
    return cls === "read" || cls === "other" || cls === "row-extraction";
  }
  if (LOCAL_READ_TOOLS.has(toolName)) return true;
  if (toolName === "Bash") {
    return (
      typeof input.command === "string" &&
      (isReadOnlyCommand(input.command) ||
        isToolResultRead(input.command) ||
        isReadOnlyNodeScript(input.command, roots))
    );
  }
  return false;
}

export type ToolPolicy = {
  /** Auto-approved, no prompt. */
  allowedTools: string[];
  /** Removed from the model's context. */
  disallowedTools: string[];
  /** Counts per class, for /health and logs. */
  summary: Record<ToolClass, number>;
};

