// Four role groups: pmo / consultant / developer / operations (was system).
const fs = require("fs");
const root = process.argv[2];
function edit(file, pairs) {
  const p = `${root}/${file}`;
  let s = fs.readFileSync(p, "utf8");
  const eol = s.includes("\r\n") ? "\r\n" : "\n";
  for (const [a, b, count = 1] of pairs) {
    const a2 = a.replace(/\n/g, eol), b2 = b.replace(/\n/g, eol);
    const n = s.split(a2).length - 1;
    if (n !== count) throw new Error(`${file}: expected ${count}, found ${n}: ${a.slice(0, 70)}`);
    s = s.split(a2).join(b2);
  }
  fs.writeFileSync(p, s);
}

