                <HtmlPreview
                  name={cboName ? `${cboName}.html` : htmlFile.name}
                  html={htmlText}
                  onDownload={() =>
                    download(
                      cboName ? `${cboName}.html` : htmlFile.name,
                      htmlText,
                      "text/html;charset=utf-8",
                    )
                  }
                  // The CBO inventory has the spec's edit mode too (`styledCbo`),
                  // so its Save needs the same way out of the frame.
                  {...(docKind === "spec" || docKind === "cbo" || docKind === "compare"
                    ? {
                        doc: docKind === "spec" ? ("spec" as const) : ("doc" as const),
                        onSaveEdited: (edited: string) =>
                          download(
                            editedName(cboName ? `${cboName}.html` : htmlFile.name),
                            edited,
                            "text/html;charset=utf-8",
                          ),
                        ...(docKind === "spec" ? { onFlow: flowEdits.onFlow } : {}),
                      }
                    : {})}
                />
              )}

              {review && wanted.includes("html") && (
                <HtmlPreview
                  name={`${review.base}.html`}
                  html={review.html}
                  onDownload={() =>
                    download(`${review.base}.html`, review.html, "text/html;charset=utf-8")
                  }
                />
              )}

              {manuals.map(({ file, html }) => (
                <HtmlPreview
                  key={file.path}
                  name={file.name}
                  html={html}
                  onDownload={() => download(file.name, html, "text/html;charset=utf-8")}
                  onSaveEdited={(edited) =>
                    download(editedName(file.name), edited, "text/html;charset=utf-8")
                  }
                />
              ))}

              {processPages.map(({ file, html }) => (
                <HtmlPreview
                  key={file.path}
                  name={file.name}
                  html={html}
                  doc="process"
                  onDownload={() => download(file.name, html, "text/html;charset=utf-8")}
                  // The page's own "Save file" (`process-theme.ts`): as built
                  // under its own name, an edited copy as `…-edited.html`.
                  onSaveEdited={(edited, asBuilt) =>
                    download(asBuilt ? file.name : editedName(file.name), edited, "text/html;charset=utf-8")
                  }
                />
              ))}

              {inventoryFile && cboName && (
                <button
                  type="button"
                  className="file-card"
                  onClick={() =>
                    download(`${cboName}.json`, bytesOf(inventoryFile), "application/json")
                  }
                  title={t.downloadFile}
                >
                  <span className="file-card-icon" aria-hidden="true">
                    <Icon name="brackets-curly" weight="fill" />
                  </span>
                  <span className="file-card-body">
                    <span className="file-card-name">{`${cboName}.json`}</span>
                    <span className="file-card-meta">
                      {t.inventoryJson} · {sizeLabel(inventoryFile.size)} ·{" "}
