  keepers.get(slug)?.stop();
  try {
    // The server builds the prompt and decides the session from these
    // answers (`lib/run-plan.ts`, `app/api/runs`). What stays here is what
    // the page itself needs: which files to wait for, and the spec dialog.
    const request: RunRequest = { slug, values, locale, how, context };
    if (crt) {
      setCreating({ survey: crt, approved: false });
      specTurn.current = 0;
      request.system = crt.system;
    } else if (obj) {
      // The object's name stands where the program's would; its design is
      // approved as a program's spec is, and it has no execution mode.
      setCreating({
        survey: { method: obj.method, executionMode: "Auto", program: obj.name, package: obj.package, transport: obj.transport },
        approved: false,
      });
      specTurn.current = 0;
      request.system = obj.system;
    } else if (rev) {
      setWanted(rev.formats);
    } else if (cmp) {
      setWanted(cmp.formats);
    } else if (cbo || manual || proc) {
      // The index as HTML with inventory.json beside it; the manual as one
      // HTML file, or two with the English companion.
      setWanted(["html"]);
      if (manual) request.cover = manual.cover;
    } else if (survey) {
      setWanted(survey.formats);
      request.answers = { depth: survey.depth, audience: survey.audience };
    }
    const documentsRun = Boolean(rev || cmp || proc || cbo || manual || survey);
    // Screenshots go with a plain skill's prompt only; no documents form takes them.
    const session = await api.startRun(request, documentsRun || crt ? [] : images.map(toAttachment));
    setSessionId(session.id);
    if (documentsRun) keepDocuments(slug, session.id);
