// Home guide: a PMO step, and the new screens named in each group's tips.
const fs = require("fs");
const root = process.argv[2];
function edit(file, pairs) {
  const p = `${root}/${file}`;
  let s = fs.readFileSync(p, "utf8");
  const eol = s.includes("\r\n") ? "\r\n" : "\n";
  for (const [a, b] of pairs) {
    const a2 = a.replace(/\n/g, eol), b2 = b.replace(/\n/g, eol);
