// Adds ops-health-check to the four READMEs (after the SmartForm Preview row) and to docs/FEATURES.md.
const fs = require("fs");
const root = process.argv[2];
const rows = {
  "README.md": "| 🩺 **Operations Health Check** | `/sc4sap:ops-health-check` — the morning check of SM / AMS operations in one report: short dumps grouped by runtime error and program and compared with the period before, the transport requests that changed a dumping program, aborted jobs, update errors and IDocs in error — with a verdict and the next step for each finding (which dump to analyze, which TCode to open). A table the system will not read is shown as *not readable*, never as empty. Read-only; user names are counted, never listed. |",
  "README.ko.md": "| 🩺 **운영 점검** | `/sc4sap:ops-health-check` — SM / AMS 운영팀의 아침 점검을 보고서 한 장으로 만들어요. 숏 덤프를 런타임 오류와 프로그램별로 묶어 이전 기간과 비교해요. 덤프가 난 프로그램을 바꾼 전송 요청, 중단된 배치 잡, 업데이트 오류, 오류 IDoc도 보여줘요. 판정과 항목별 다음 할 일(분석할 덤프, 열어 볼 TCode)을 함께 적어요. 시스템이 읽게 해 주지 않는 테이블은 '없음'이 아니라 '읽을 수 없음'으로 표시해요. 조회 전용이고, 사용자 이름은 수만 세요. |",
  "README.ja.md": "| 🩺 **運用ヘルスチェック** | `/sc4sap:ops-health-check` — SM / AMS 運用チームの朝の点検を1つのレポートにまとめます。ショートダンプをランタイムエラーとプログラムごとにまとめて前期間と比較し、ダンプしたプログラムを変更した移送依頼、中断したジョブ、更新エラー、エラー IDoc を示します。判定と項目ごとの次の一手(分析するダンプ、開く TCode)付き。システムが読ませないテーブルは「なし」ではなく「読めない」と表示します。照会のみ、ユーザー名は数だけ数えます。 |",
  "README.de.md": "| 🩺 **Betriebs-Check** | `/sc4sap:ops-health-check` — der Morgen-Check des SM- / AMS-Betriebs in einem Bericht: Kurzdumps nach Laufzeitfehler und Programm gruppiert und mit dem Vorzeitraum verglichen, die Transportaufträge, die ein dumpendes Programm geändert haben, abgebrochene Jobs, Verbuchungsfehler und IDocs im Fehlerstatus — mit Urteil und dem nächsten Schritt je Befund (welcher Dump analysiert, welche TCode geöffnet wird). Eine Tabelle, die das System nicht lesen lässt, erscheint als *nicht lesbar*, nie als leer. Nur lesend; Benutzernamen werden gezählt, nie aufgelistet. |",
};
for (const [file, row] of Object.entries(rows)) {
  const p = `${root}/${file}`;
  const text = fs.readFileSync(p, "utf8");
  const eol = text.includes("\r\n") ? "\r\n" : "\n";
  const lines = text.split(eol);
  const at = lines.findIndex((l) => l.startsWith("| ") && l.includes("`/sc4sap:smartform-preview` —"));
  if (at < 0) throw new Error(`${file}: SmartForm Preview row not found`);
  if (lines.some((l) => l.includes("/sc4sap:ops-health-check"))) continue;
  lines.splice(at + 1, 0, row);
  fs.writeFileSync(p, lines.join(eol));
}

const fp = `${root}/docs/FEATURES.md`;
let f = fs.readFileSync(fp, "utf8");
const eol = f.includes("\r\n") ? "\r\n" : "\n";
const tableRow = "| `sc4sap:analyze-symptom` | Step-by-step SAP operational error/symptom analysis (dumps, logs, SAP Note candidates) |";
if (!f.includes(tableRow)) throw new Error("FEATURES table row not found");
if (!f.includes("sc4sap:ops-health-check")) {
  f = f.replace(tableRow, `${tableRow}${eol}| \`sc4sap:ops-health-check\` | Daily operations health check — dumps grouped and compared with the previous period, the transports that changed a dumping program, aborted jobs, update errors, IDocs in error; verdict + next steps (read-only) |`);
  const head = "### `/sc4sap:smartform-preview`";
  const section = [
    "### `/sc4sap:ops-health-check`",
    "The morning check of SM / AMS operations. `scripts/ops/build-ops-check.mjs collect` reads, for a period (default since yesterday) and the period of the same length before it: the short dumps (`RuntimeListDumps` — the ADT feed and, on ECC, the ST22 list), the transport requests from a week before the period on with their texts and code objects (E070 / E07T / E071), aborted jobs (TBTCO status A with the first step's program), update requests with an error (VBHDR) and IDocs in an error status (EDIDC). `build` groups the dumps by runtime error and program, marks the groups that are new against the previous period, lists next to a group the requests that changed its program, include, function group or class before its last dump, and gives a verdict (red / amber / green) with the next step for each finding — `/sc4sap:analyze-symptom` for a dump group, SM37 / SM13 / BD87 for the rest. On BASIS < 7.50 the dispatcher reads customizing and system tables only, so jobs, updates and IDocs show as *not readable — check in SM37 / SM13 / WE02*, never as empty. No business document contents are read; user names are counted, never listed. One self-contained HTML page (ko / en / ja, light and dark, A4 landscape print) under `ops-check/<to>/` of the profile artifact base.",
    "",
  ].join(eol);
  if (!f.includes(head)) throw new Error("FEATURES section anchor not found");
  f = f.replace(head, `${section}${eol}${head}`);
  fs.writeFileSync(fp, f);
}
console.log("ok");

