// Patch ZMCP_ADT_DISPATCH on the active profile's system: add TBTCO / TBTCP / VBHDR / EDIDC to the
// TABLE_READ allow list. Works on the exact source the system returned (GetFunctionModule output "file"),
// changes two places only, and refuses unless each anchor matches exactly once.
//
//   node patch-dispatch.mjs <source.abap> --dry-run
//   node patch-dispatch.mjs <source.abap> --transport <TR>      (uploads + activates through the MCP bridge)
import { readFileSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

const [file, ...rest] = process.argv.slice(2);
const dry = rest.includes('--dry-run');
const tr = rest[rest.indexOf('--transport') + 1];
const src = readFileSync(file, 'utf8');
const eol = src.includes('\r\n') ? '\r\n' : '\n';

const pairs = [
  [
    `     AND lv_tab <> 'EDP13' AND lv_tab <> 'EDP21' AND lv_tab <> 'SWETYPECOU'.`,
    `     AND lv_tab <> 'EDP13' AND lv_tab <> 'EDP21' AND lv_tab <> 'SWETYPECOU'${eol}     AND lv_tab <> 'TBTCO' AND lv_tab <> 'TBTCP' AND lv_tab <> 'VBHDR' AND lv_tab <> 'EDIDC'.`,
  ],
  [
    `  " are readable for the S/4HANA conversion readiness report.`,
    `  " are readable for the S/4HANA conversion readiness report.${eol}` +
      `  " For ops-health-check the operations headers are listed by name though${eol}` +
      `  " their class is L / A: job headers and steps (TBTCO, TBTCP), update${eol}` +
      `  " request headers (VBHDR) and IDoc control records (EDIDC). Job logs,${eol}` +
      `  " update data (VBDATA, VBMOD) and IDoc data / status texts stay closed.`,
  ],
];
let out = src;
for (const [a, b] of pairs) {
  const n = out.split(a).length - 1;
  if (n !== 1) throw new Error(`anchor found ${n}×: ${a.trim().slice(0, 60)}`);
  out = out.replace(a, b);
}
if (out.includes("'TBTCO'") === src.includes("'TBTCO'")) throw new Error('nothing changed');
const added = out.split(eol).length - src.split(eol).length;
writeFileSync(file.replace(/\.abap$/, '.patched.abap'), out);
console.log(JSON.stringify({ ok: true, linesBefore: src.split(eol).length, linesAfter: out.split(eol).length, added }));
if (dry) process.exit(0);
if (!/^[A-Z0-9]{3}K\d{6}$/.test(tr || '')) throw new Error('--transport <TR> required (e.g. HKDK9A2XYZ)');

const reader = await import(pathToFileURL('C:/Users/pssps/Documents/Projects/sc4sap_project/sc4sap/scripts/config/sap-reader.mjs').href);
const client = await reader.connect('dispatch-allowlist');
try {
  const res = await client.callTool({
    name: 'UpdateFunctionModule',
    arguments: { function_group_name: 'ZMCP_ADT_UTILS', function_module_name: 'ZMCP_ADT_DISPATCH', source_code: out, transport_request: tr, activate: true },
  });
  console.log((res?.content?.[0]?.text ?? '').slice(0, 1500));
  if (res?.isError) process.exit(1);
} finally {
  await client.close().catch(() => {});
}

