// Page guides (ko / en / ja) for the screens added 2026-11-16, inserted before each locale's "skill.sap-doctor".
const fs = require("fs");
const p = process.argv[2];
let s = fs.readFileSync(p, "utf8");
const eol = s.includes("\r\n") ? "\r\n" : "\n";

const g = (title, steps) => ({ title, steps });
const st = (title, body, tips) => (tips ? { title, body, tips } : { title, body });

const T = {
  ko: {
    "project-dashboard": g("프로젝트 대시보드 가이드", {
      intro: st("프로젝트 대시보드", "프로젝트 한 건을 한 장의 페이지로 만들어요. KPI, Q-gate 마일스톤, WBS와 간트, 팀, SAP 실적(전송 요청, 오브젝트, 덤프)을 담아요."),
      fields: st("입력", "유형, 코드, 이름, 시작일·오픈일, 모듈을 넣어요. 나머지는 선택이에요.", ["패키지: 이 패키지의 오브젝트와 전송 요청이 실적이 돼요.", "팀: 한 줄에 한 명. 이름 · 역할 · 모듈 · SAP 사용자 · 기간.", "WRICEF: 한 줄에 하나. 유형 · 제목 · 모듈 · 단계."]),
      run: st("실행", "「실행」을 누르면 시작돼요. SAP에서 실적을 읽는 단계는 승인 창이 한 번 떠요."),
      result: st("결과", "대시보드 페이지가 아래에 나와요. 페이지 안에서 편집하고, 「PDF로 저장」이나 .html로 내려받을 수 있어요."),
      tips: st("알아 두면 좋아요", "결과는 서버에 저장되지 않아요. 내려받은 페이지를 계속 고쳐 쓰세요."),
    }),
    "role-matrix": g("권한 매트릭스 가이드", {
      intro: st("권한 매트릭스", "역할과 권한을 워크북 한 장으로 정리해요. 업무 역할, PFCG 역할, 역할 × T-code, 사용자 배정, SoD 충돌까지 담아요."),
      fields: st("입력", "방식, 문서 코드, 모듈은 꼭 넣어요.", ["새로 설계: 모듈 컨설턴트가 역할과 T-code를 제안해요. 조직 값을 넣으면 파생 역할을 나눠요.", "SAP에서 읽기: 역할 패턴(예: Z_PM*)에 맞는 PFCG 역할을 읽어요. 사용자는 ID만 읽어요."]),
      run: st("실행", "「실행」을 누르면 시작돼요. SAP에서 역할을 읽는 단계는 승인 창이 떠요."),
      result: st("결과", "시트별 워크북이 아래에 나와요. 페이지 안에서 편집하고 시트마다 CSV로 내보낼 수 있어요."),
      tips: st("알아 두면 좋아요", "SoD 충돌은 자동으로 점검돼요. 결과는 서버에 남지 않으니 꼭 내려받아 두세요."),
    }),
    "interface-mapping-spec": g("인터페이스 매핑 정의서 가이드", {
      intro: st("인터페이스 매핑 정의서", "표준 양식의 매핑 정의서를 만들어요. SAP 필드는 DDIC에서 읽고, 상대 시스템 필드와 변환 규칙을 제안해요."),
      fields: st("입력", "시나리오, 모듈, 인터페이스 이름, SAP 필드는 꼭 넣어요.", ["SAP 필드: 테이블·구조·함수 모듈 이름, 필드 목록, 또는 목적 설명 중 하나를 적어요.", "인터페이스 ID는 비우면 프로젝트의 다음 번호를 써요."]),
      run: st("실행", "「실행」을 누르면 시작돼요. 필드 목록을 확정할 때 한 번 물어봐요."),
      result: st("결과", "정의서 페이지가 아래에 나와요. 페이지 안에서 고치고 「PDF로 저장」이나 .html로 내려받아요."),
      tips: st("알아 두면 좋아요", "새 Z 구조가 필요하면 「오브젝트 생성」으로 이어서 만들 수 있어요."),
    }),
    "smartform-preview": g("SmartForm 미리보기 가이드", {
      intro: st("SmartForm 미리보기", "출력 프로그램 없이 SmartForm의 예상 출력물을 그려요. 샘플 값은 필드 타입에 맞춰 지어 넣어요."),
      fields: st("입력", "SmartForm 이름만 넣으면 돼요. 품목 행 수는 비우면 3행이에요."),
      run: st("실행", "「실행」을 누르면 시작돼요. 실제 전표 데이터는 쓰지 않아요."),
      result: st("결과", "JPG가 화면에 바로 나오고, 아래 HTML 미리보기에서 「PDF로 저장」할 수 있어요. 잘리는 칸은 보고서에 따로 적혀요."),
      tips: st("알아 두면 좋아요", "첫 페이지만 그려요. 레이아웃 문제는 보고서로 알려주고, 양식 자체는 고치지 않아요."),
    }),
    assist: g("업무 어시스턴트 가이드", {
      intro: st("업무 어시스턴트", "실제 전표를 조회해요. 미결 PO, 출하·청구 보류, 생산오더, FI 전표, 보전오더 같은 업무 질문에 답해요."),
      fields: st("입력", "궁금한 것을 문장으로 적어요. 예: 「이번 주 납기인 벤더 100023의 미결 PO」."),
      run: st("실행", "「실행」을 누르면 조회를 시작해요. 빠진 조건은 되물어요."),
      result: st("결과", "조회 결과 표가 아래에 나와요. 아래 입력창으로 이어서 물어볼 수 있어요."),
      tips: st("알아 두면 좋아요", "웹에서는 조회만 돼요. 전기·승인 같은 변경은 아직 지원하지 않아요."),
    }),
    "ops-health-check": g("운영 점검 가이드", {
      intro: st("운영 점검", "SM 운영팀의 아침 점검을 보고서 한 장으로 만들어요. 덤프, 중단된 잡, 업데이트 오류, 오류 IDoc, 최근 전송 요청을 한 번에 봐요."),
