const lit = (v, ind) => {
  if (Array.isArray(v)) return `[${eol}${v.map((x) => `${ind}  ${JSON.stringify(x)},`).join(eol)}${eol}${ind}]`;
  if (typeof v === "object") return `{${eol}${Object.entries(v).map(([k, x]) => `${ind}  ${/^[a-z]\w*$/i.test(k) ? k : JSON.stringify(k)}: ${lit(x, `${ind}  `)},`).join(eol)}${eol}${ind}}`;
  return JSON.stringify(v);
};
const block = (texts) => Object.entries(texts).map(([slug, v]) => `    ${JSON.stringify(`skill.${slug}`)}: ${lit(v, "    ")},`).join(eol) + eol;

const anchor = `    "skill.sap-doctor": {`;
const parts = s.split(anchor);
if (parts.length !== 4) throw new Error(`expected 3 sap-doctor guides, found ${parts.length - 1}`);
if (s.includes('"skill.ops-health-check"')) throw new Error("already added");
// Order of the locales in the file: ko, en, ja.
s = parts[0] + block(T.ko) + anchor + parts[1] + block(T.en) + anchor + parts[2] + block(T.ja) + anchor + parts[3];
fs.writeFileSync(p, s);
console.log("ok");

