input.new_string:
const FEED_PAGE = 100;
const FEED_PAGES = 30;

/**
 * Every dump from `from` to `to`. On ECC the ST22 list (`st22`) honours the dates in one call. The ADT feed
 * (S/4, and ECC's last 24 h) ignores them and returns the newest entries a page at a time (100 on S/4), so it
 * is paged with `skip` until an entry older than `from` shows up. `complete` is false when the pages ran out
 * first — the caller must not compare against a period it did not reach.
 */
export async function readDumpRange(client, from, to) {
  const call = async (args) => {
    const res = await client.callTool({ name: 'RuntimeListDumps', arguments: args });
    const text = res?.content?.[0]?.text ?? '';
    if (res?.isError) throw new Error(text.slice(0, 300));
    return JSON.parse(text);
  };
  try {
    const first = await call({ date_from: from, date_to: to, top: 1000 });
    const rows = dumpsOf(first);
    if (first?.st22) return { ok: true, complete: !first.st22.truncated, rows: rows.filter((d) => d.date >= from && d.date <= to) };
    const feedCount = (json) => {
      const e = json?.payload?.['atom:feed']?.['atom:entry'];
      return Array.isArray(e) ? e.length : e ? 1 : 0;
    };
    let got = feedCount(first);
    let skip = got;
    let complete = got < FEED_PAGE || rows.some((d) => d.date && d.date < from);
    for (let page = 1; !complete && page < FEED_PAGES; page += 1) {
      const next = await call({ top: FEED_PAGE, skip });
      got = feedCount(next);
      const more = dumpsOf(next);
      const seen = new Set(rows.map((r) => r.id));
      rows.push(...more.filter((r) => !seen.has(r.id)));
      skip += got;
      complete = got < FEED_PAGE || more.some((d) => d.date && d.date < from);
    }
    return { ok: true, complete, rows: rows.filter((d) => d.date >= from && d.date <= to) };
  } catch (e) {
    return { ok: false, complete: false, rows: [], error: String(e?.message ?? e).slice(0, 300) };
  }
}

