  it('is incomplete when the server did not reach date_from, and the model then calls nothing new', async () => {
    const r = await readDumpRange(client(feed([entry(day('2026-11-16', 1), 'TIME_OUT')], { pages: 20, complete: false })), '2026-11-01', '2026-11-16');
