"""Print the structure of a test-scenario workbook: sheets, used range, merged areas,
the first rows (header / cover), and per column the first non-empty values."""
import sys
import openpyxl

path = sys.argv[1]
rows_to_show = int(sys.argv[2]) if len(sys.argv) > 2 else 14
wb = openpyxl.load_workbook(path, data_only=True)
for ws in wb.worksheets:
    print(f"\n=== sheet '{ws.title}'  range {ws.dimensions}  max_row {ws.max_row}  max_col {ws.max_column}  state {ws.sheet_state}")
    merged = [str(m) for m in list(ws.merged_cells.ranges)[:25]]
    print("merged:", ", ".join(merged), "..." if len(ws.merged_cells.ranges) > 25 else "")
    widths = {k: round(v.width or 0) for k, v in ws.column_dimensions.items() if v.width}
    print("widths:", dict(list(widths.items())[:30]))
    for r in range(1, min(ws.max_row, rows_to_show) + 1):
        vals = []
        for c in range(1, min(ws.max_column, 30) + 1):
            v = ws.cell(r, c).value
            if v is not None and str(v).strip() != "":
                s = str(v).replace("\n", " / ")
                vals.append(f"{ws.cell(r, c).coordinate}={s[:60]}")
        if vals:
            print(f"r{r}: " + " | ".join(vals))
    dv = getattr(ws, "data_validations", None)
    if dv and dv.dataValidation:
        for d in dv.dataValidation[:8]:
            print("validation:", d.sqref, d.type, (d.formula1 or "")[:80])

