// Adds uat-scenarios to the four READMEs (after the ops-health-check row) and to docs/FEATURES.md.
const fs = require("fs");
const root = process.argv[2];
const rows = {
  "README.md": "| 🧪 **UAT Scenarios** | `/sc4sap:uat-scenarios` — UAT test scenarios kept as one editable set per module: scenarios with STEP rows (activity, system, T-code, check points, input data, expected output, test user, result per test cycle, follow-up). The module consultant drafts it and proposes changes item by item for you to accept or reject; T-codes are checked in the system; gaps and per-cycle progress are listed; Excel export in the integrated-test or the flat scenario-list layout. |",
  "README.ko.md": "| 🧪 **UAT 시나리오** | `/sc4sap:uat-scenarios` — 모듈별 UAT 테스트 시나리오를 고쳐 가며 쓰는 묶음 하나로 관리해요. 시나리오마다 STEP 행(활동, 시스템, T-code, 확인 항목, 입력 데이터, 기대 결과, 테스트 사용자, 회차별 결과, 후속 조치)이 있어요. 모듈 컨설턴트가 초안을 쓰고, 고칠 점은 항목별로 제안해서 받거나 버릴 수 있어요. T-code는 시스템에서 확인하고, 빠진 점과 회차별 진행률을 보여줘요. 엑셀은 통합 테스트형이나 목록형으로 내보내요. |",
  "README.ja.md": "| 🧪 **UAT シナリオ** | `/sc4sap:uat-scenarios` — モジュールごとの UAT テストシナリオを編集し続けるセット1つで管理します。シナリオごとの STEP 行(活動、システム、T-code、確認項目、入力データ、期待結果、テストユーザー、回次別結果、フォローアップ)。モジュールコンサルタントが下書きし、修正は項目ごとに提案して採否を選べます。T-code はシステムで確認し、抜けと回次別の進捗を示します。Excel は統合テスト形式か一覧形式で出力します。 |",
  "README.de.md": "| 🧪 **UAT-Szenarien** | `/sc4sap:uat-scenarios` — UAT-Testszenarien als ein bearbeitbares Set pro Modul: Szenarien mit STEP-Zeilen (Aktivität, System, T-Code, Prüfpunkte, Eingabedaten, erwartetes Ergebnis, Testbenutzer, Ergebnis je Testzyklus, Folgeaktion). Der Modulberater entwirft es und schlägt Änderungen einzeln vor, die Sie annehmen oder verwerfen; T-Codes werden im System geprüft; Lücken und Fortschritt je Zyklus werden gezeigt; Excel-Export im Integrationstest- oder Listenlayout. |",
};
for (const [file, row] of Object.entries(rows)) {
  const p = `${root}/${file}`;
  const text = fs.readFileSync(p, "utf8");
  const eol = text.includes("\r\n") ? "\r\n" : "\n";
  const lines = text.split(eol);
  if (lines.some((l) => l.includes("/sc4sap:uat-scenarios"))) continue;
  const at = lines.findIndex((l) => l.startsWith("| ") && l.includes("`/sc4sap:ops-health-check` —"));
  if (at < 0) throw new Error(`${file}: ops-health-check row not found`);
  lines.splice(at + 1, 0, row);
  fs.writeFileSync(p, lines.join(eol));
}
const fp = `${root}/docs/FEATURES.md`;
let f = fs.readFileSync(fp, "utf8");
const eol = f.includes("\r\n") ? "\r\n" : "\n";
if (!f.includes("sc4sap:uat-scenarios")) {
  const tableAnchor = f.split(eol).find((l) => l.startsWith("| `sc4sap:ops-health-check` |"));
  if (!tableAnchor) throw new Error("FEATURES table anchor");
  f = f.replace(tableAnchor, `${tableAnchor}${eol}| \`sc4sap:uat-scenarios\` | UAT scenario set per module — consultant draft, item-by-item proposals, T-code check, per-cycle progress, Excel export in two layouts (read-only on SAP) |`);
  const head = "### `/sc4sap:ops-health-check`";
  const section = [
    "### `/sc4sap:uat-scenarios`",
