/**
 * The plugin's UAT model and Excel writer, loaded on the server at run time.
 *
 * One source of truth: the web normalizes, validates, applies proposals and
 * exports with exactly the code `/sc4sap:uat-scenarios` runs in a terminal
 * (`plugin_module/scripts/uat/`), instead of a copy that drifts. The modules
 * are plain Node ESM outside this app, so they are imported by file URL and
 * kept out of the bundle.
 *
 * Server only — the routes under `app/api/uat/`.
 */
import "server-only";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";

export type UatSet = {
  id: string;
  module: string;
  title: string;
  lang: string;
  cycles: string[];
  scenarios: { id: string; title: string; steps: { id: string }[] }[];
  [key: string]: unknown;
};
export type UatIssue = { level: "error" | "warn"; path: string; text: string };
export type UatProgress = {
  scenarios: number;
  steps: number;
  byCycle: Record<string, { pass: number; fail: number; blocked: number; open: number }>;
  byStatus: Record<string, number>;
};
export type UatOp = Record<string, unknown> & { op: string };

type Model = {
  normalize(set: unknown): UatSet;
  validate(set: UatSet): UatIssue[];
  progress(set: UatSet): UatProgress;
  applyPatch(set: UatSet, ops: UatOp[]): { set: UatSet; applied: number[]; skipped: { index: number; op: string; why: string }[] };
};
type Xlsx = { layoutA(set: UatSet): Buffer; layoutB(set: UatSet): Buffer };

/** The plugin the backend runs: `SC4SAP_PLUGIN_PATH`, else the repo's `plugin_module` next to `web/`. */
function pluginRoot(): string {
  return process.env.SC4SAP_PLUGIN_PATH || resolve(process.cwd(), "..", "plugin_module");
}

const load = async <T>(file: string): Promise<T> =>
  (await import(/* webpackIgnore: true */ /* turbopackIgnore: true */ pathToFileURL(resolve(pluginRoot(), "scripts", "uat", file)).href)) as T;

export const uatModel = (): Promise<Model> => load<Model>("uat-model.mjs");
export const uatXlsx = (): Promise<Xlsx> => load<Xlsx>("uat-xlsx.mjs");

/** A set ID as the plugin accepts it. */
export const UAT_ID = /^[A-Za-z0-9_-]{1,30}$/;

