/**
 * GET /api/uat/<id>/export?layout=A|B — the set as an .xlsx, written by the
 * plugin's own writer (`scripts/uat/uat-xlsx.mjs`): A is the integrated-test
 * workbook (schedule, activities, a sheet per scenario), B the flat list.
 */
import { apiConnected } from "@/lib/auth/api-guard";
import { uatSets } from "@/lib/mongo";
import { UAT_ID, uatModel, uatXlsx } from "@/lib/uat-plugin";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

export async function GET(request: Request, { params }: { params: Promise<{ id: string }> }): Promise<Response> {
  const auth = await apiConnected();
  if ("response" in auth) return auth.response;
  const { id } = await params;
  if (!UAT_ID.test(id)) return Response.json({ error: "bad id" }, { status: 400 });
  const layout = new URL(request.url).searchParams.get("layout") === "B" ? "B" : "A";
  try {
    const doc = await (await uatSets()).findOne({ accountId: auth.account.id, setId: id });
    if (!doc) return Response.json({ error: "not found" }, { status: 404 });
    const set = (await uatModel()).normalize(doc.set);
    const xlsx = await uatXlsx();
    const bytes = layout === "A" ? xlsx.layoutA(set) : xlsx.layoutB(set);
    return new Response(new Uint8Array(bytes), {
      headers: {
        "Content-Type": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        "Content-Disposition": `attachment; filename="${id}-uat-${layout}.xlsx"`,
        "Cache-Control": "no-store",
      },
    });
  } catch (err) {
    return Response.json({ error: (err as Error).message }, { status: 503 });
  }
}

