const RESULT_MARK: Record<string, string> = { pass: "O", fail: "X", blocked: "△", "": "–" };
const LANG: Record<string, string> = { ko: "Korean", en: "English", ja: "Japanese" };

/** One line per operation, for the reader to judge. */
function describe(op: Op): string {
  const sc = typeof op.scenario === "string" ? op.scenario : op.scenario?.id || op.scenario?.title || "";
  const st = typeof op.step === "string" ? op.step : op.step?.activity || "";
  const val = Array.isArray(op.value) ? op.value.join(" · ") : typeof op.value === "string" ? op.value : "";
  switch (op.op) {
    case "set-step": return `${sc} · ${st} · ${op.field} → ${val}`;
    case "set-scenario": return `${sc} · ${op.field} → ${val}`;
    case "add-step": return `${sc} · ${op.after ? `after ${op.after} · ` : ""}+ ${st}`;
    case "remove-step": return `${sc} · − ${st}`;
    case "add-scenario": return `+ ${typeof op.scenario === "object" ? `${op.scenario?.id ?? ""} ${op.scenario?.title ?? ""}` : sc}`;
    default: return JSON.stringify(op).slice(0, 160);
  }
}

const lines = (v: string): string[] => v.split(/\r?\n/).map((x) => x.trim()).filter(Boolean);

export function UatWorkbench() {
  const { locale } = useLocale();
  const t = T[locale === "ko" ? "ko" : "en"];
  const [list, setList] = useState<Listed[]>([]);
  const [current, setCurrent] = useState<UatSet | null>(null);
  const [issues, setIssues] = useState<Issue[]>([]);
  const [progress, setProgress] = useState<Progress | null>(null);
  const [dirty, setDirty] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [draftForm, setDraftForm] = useState({ id: "", module: "MM", title: "", scope: "" });
  const [request, setRequest] = useState("");
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [aiMode, setAiMode] = useState<"draft" | "patch" | null>(null);
  const [proposal, setProposal] = useState<{ ops: Op[]; picked: boolean[] } | null>(null);
  const [skipped, setSkipped] = useState<{ index: number; why: string }[]>([]);
  const stream = useSessionStream(sessionId);

  const call = useCallback(async <R,>(url: string, init?: RequestInit): Promise<R> => {
    const res = await fetch(url, { ...init, headers: { "Content-Type": "application/json", ...(init?.headers ?? {}) } });
    const body = (await res.json().catch(() => ({}))) as R & { error?: string };
    if (!res.ok) throw new Error(body.error || `HTTP ${res.status}`);
    return body;
  }, []);

  const refreshList = useCallback(async () => {
    try { setList((await call<{ sets: Listed[] }>("/api/uat")).sets); } catch (e) { setError((e as Error).message); }
  }, [call]);
  useEffect(() => { void refreshList(); }, [refreshList]);

  const take = (body: { set: UatSet; issues: Issue[]; progress: Progress }) => {
    setCurrent(body.set); setIssues(body.issues); setProgress(body.progress); setDirty(false);
  };
  const open = async (id: string) => {
    setError(null); setProposal(null); setSkipped([]);
    try { take(await call(`/api/uat/${id}`)); } catch (e) { setError((e as Error).message); }
  };
  const create = async (set: Partial<UatSet>) => {
    setBusy(true); setError(null);
    try { take(await call("/api/uat", { method: "POST", body: JSON.stringify({ set }) })); await refreshList(); }
    catch (e) { setError((e as Error).message); } finally { setBusy(false); }
  };
  const save = async () => {
    if (!current) return;
    setBusy(true); setError(null);
    try { take(await call(`/api/uat/${current.id}`, { method: "PUT", body: JSON.stringify({ set: current }) })); await refreshList(); }
    catch (e) { setError((e as Error).message); } finally { setBusy(false); }
  };

  // Edits stay local until Save.
  const edit = (fn: (s: UatSet) => void) => setCurrent((prev) => {
    if (!prev) return prev;
    const next = structuredClone(prev); fn(next); setDirty(true); return next;
  });

  // ---- AI ----
  const startAi = async (mode: "draft" | "patch") => {
    setError(null); setProposal(null); setSkipped([]);
    const values = mode === "draft"
      ? { Mode: "draft", Module: draftForm.module, Request: `${draftForm.title} — ${draftForm.scope}`, Set: "", Language: LANG[locale] ?? "Korean" }
      : { Mode: "patch", Module: current?.module ?? "MM", Request: request, Set: JSON.stringify(current), Language: LANG[locale] ?? "Korean" };
    try {
      const session = await api.startRun({ slug: "uat-scenarios", values, locale, how: null, context: null });
      setAiMode(mode); setSessionId(session.id);
    } catch (e) { setError((e as Error).message); }
  };
  const answer = useMemo(() => {
    const last = [...stream.items].reverse().find((i) => i.kind === "assistant");
    return last && last.kind === "assistant" ? last.text : "";
  }, [stream.items]);
  const settled = sessionId !== null && stream.status === "idle" && !stream.streaming && answer !== "";
  useEffect(() => {
    if (!settled || !aiMode) return;
    const json = lastJsonBlock(answer);
    setAiMode(null); setSessionId(null);
    if (aiMode === "draft") {
      if (!json || typeof json !== "object") { setError(t.noJson); return; }
      void create({ ...(json as Partial<UatSet>), id: draftForm.id, title: draftForm.title || (json as UatSet).title, module: draftForm.module });
    } else {
      if (!Array.isArray(json)) { setError(t.noJson); return; }
      setProposal({ ops: json as Op[], picked: (json as Op[]).map(() => true) });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [settled]);
  const applyPicked = async () => {
    if (!current || !proposal) return;
    const ops = proposal.ops.filter((_, i) => proposal.picked[i]);
    setBusy(true);
    try {
      const body = await call<{ set: UatSet; issues: Issue[]; progress: Progress; skipped: { index: number; why: string }[] }>(`/api/uat/${current.id}/patch`, { method: "POST", body: JSON.stringify({ ops }) });
      take(body); setSkipped(body.skipped); setProposal(null); await refreshList();
    } catch (e) { setError((e as Error).message); } finally { setBusy(false); }
  };

  const pending = stream.pending[0];

  return (
    <div className="uat">
      <aside className="uat-sets">
        <h2>{t.sets}</h2>
        <ul>
          {list.map((s) => (
            <li key={s.id}>
              <button type="button" className={current?.id === s.id ? "is-on" : ""} onClick={() => void open(s.id)}>
                <strong>{s.id}</strong> <span>{s.module}</span><br /><small>{s.title}</small>
              </button>
            </li>
          ))}
        </ul>
        <div className="uat-new">
          <h3>{t.newSet}</h3>
          <input placeholder={t.id} value={draftForm.id} onChange={(e) => setDraftForm({ ...draftForm, id: e.target.value })} />
          <input placeholder={t.module} value={draftForm.module} onChange={(e) => setDraftForm({ ...draftForm, module: e.target.value.toUpperCase() })} />
          <input placeholder={t.title} value={draftForm.title} onChange={(e) => setDraftForm({ ...draftForm, title: e.target.value })} />
          <textarea placeholder={t.scope} rows={3} value={draftForm.scope} onChange={(e) => setDraftForm({ ...draftForm, scope: e.target.value })} />
          <div className="uat-row">
            <button type="button" className="ghost" disabled={busy || !draftForm.id} onClick={() => void create({ id: draftForm.id, module: draftForm.module, title: draftForm.title, scenarios: [] })}>{t.empty}</button>
            <button type="button" disabled={busy || !draftForm.id || !draftForm.scope || sessionId !== null} onClick={() => void startAi("draft")}><Icon name="sparkle" /> {t.draft}</button>
          </div>
        </div>
      </aside>

      <section className="uat-main">
        {error && <p className="uat-error">{error}</p>}
        {sessionId && (
          <p className="uat-working"><Icon name="circle-notch" className="spin" /> {t.working}</p>
        )}
        {pending && (
          <div className="uat-approval">
            <span>{t.waiting}: <code>{pending.toolName}</code></span>
            <button type="button" onClick={() => void api.respondToPermission(sessionId!, pending.reqId, { behavior: "allow" })}>{t.approve}</button>
            <button type="button" className="ghost" onClick={() => void api.respondToPermission(sessionId!, pending.reqId, { behavior: "deny", message: "Denied by the reader" })}>{t.deny}</button>
          </div>
        )}
        {!current ? <p className="uat-empty">{t.pick}</p> : (
          <>
            <header className="uat-head">
              <input className="uat-title" value={current.title} onChange={(e) => edit((s) => { s.title = e.target.value; })} />
              <span className="uat-meta">{current.id} · {current.module}</span>
              <span className={`uat-dirty${dirty ? " is-on" : ""}`}>{dirty ? t.unsaved : t.saved}</span>
              <button type="button" disabled={busy || !dirty} onClick={() => void save()}><Icon name="floppy-disk" /> {t.save}</button>
              <a className="ghost button" href={`/api/uat/${current.id}/export?layout=A`}><Icon name="microsoft-excel-logo" /> {t.exportA}</a>
              <a className="ghost button" href={`/api/uat/${current.id}/export?layout=B`}><Icon name="microsoft-excel-logo" /> {t.exportB}</a>
            </header>

            {progress && (
              <div className="uat-progress">
                {current.cycles.map((c) => {
                  const p = progress.byCycle[c];
                  return p ? <span key={c}><b>{c}</b> O {p.pass} · X {p.fail} · △ {p.blocked} · – {p.open}</span> : null;
                })}
              </div>
            )}

            <details className="uat-issues" open={issues.length > 0}>
              <summary>{issues.length ? `${t.issues} (${issues.length})` : t.noIssues}</summary>
              <ul>{issues.slice(0, 30).map((i, k) => <li key={k} className={i.level}><code>{i.path}</code> {i.text}</li>)}</ul>
            </details>

            <div className="uat-suggest">
              <h3><Icon name="sparkle" /> {t.suggest}</h3>
              <textarea rows={2} placeholder={t.suggestHint} value={request} onChange={(e) => setRequest(e.target.value)} />
              <button type="button" disabled={!request.trim() || sessionId !== null || dirty} title={dirty ? t.unsaved : undefined} onClick={() => void startAi("patch")}>{t.run}</button>
              {proposal && (
                <div className="uat-proposal">
                  <h4>{t.proposal} ({proposal.ops.length})</h4>
                  <ol>
                    {proposal.ops.map((op, i) => (
                      <li key={i}>
                        <label>
                          <input type="checkbox" checked={proposal.picked[i]} onChange={(e) => setProposal({ ...proposal, picked: proposal.picked.map((v, k) => (k === i ? e.target.checked : v)) })} />
                          <span>{describe(op)}</span>
                        </label>
                      </li>
                    ))}
                  </ol>
                  <div className="uat-row">
                    <button type="button" disabled={busy || !proposal.picked.some(Boolean)} onClick={() => void applyPicked()}>{t.apply}</button>
                    <button type="button" className="ghost" onClick={() => setProposal(null)}>{t.discard}</button>
                  </div>
                </div>
              )}
              {skipped.length > 0 && (
                <p className="uat-skipped">{t.skipped}: {skipped.map((s) => `#${s.index + 1} ${s.why}`).join(" · ")}</p>
              )}
            </div>

            {current.scenarios.map((sc, si) => (
              <article key={sc.id} className="uat-scenario">
                <header>
                  <code>{sc.id}</code>
                  <input className="uat-sc-title" value={sc.title} onChange={(e) => edit((s) => { s.scenarios[si]!.title = e.target.value; })} />
                </header>
                <div className="uat-sc-fields">
                  {(Object.keys(t.scenarioFields) as (keyof typeof t.scenarioFields)[]).map((f) => (
                    <label key={f}>
                      <span>{t.scenarioFields[f]}</span>
                      <input value={sc[f]} onChange={(e) => edit((s) => { s.scenarios[si]![f] = e.target.value; })} />
                    </label>
                  ))}
                </div>
                <div className="uat-grid-wrap">
                  <table className="uat-grid">
                    <thead>
                      <tr>
                        {(["id", "activity", "system", "tcode", "checks", "inputs", "outputs", "user"] as const).map((c) => <th key={c}>{t.cols[c]}</th>)}
                        {current.cycles.map((c) => <th key={c}>{c}</th>)}
                        <th>{t.cols.status}</th><th>{t.cols.followUp}</th><th />
                      </tr>
                    </thead>
                    <tbody>
                      {sc.steps.map((st, ti) => {
                        const set = (fn: (x: Step) => void) => edit((s) => fn(s.scenarios[si]!.steps[ti]!));
                        return (
                          <tr key={st.id}>
                            <td><code>{st.id}</code></td>
                            <td><textarea rows={2} value={st.activity} onChange={(e) => set((x) => { x.activity = e.target.value; })} /></td>
                            <td><input value={st.system} onChange={(e) => set((x) => { x.system = e.target.value; })} /></td>
                            <td><input value={st.tcode} onChange={(e) => set((x) => { x.tcode = e.target.value.toUpperCase(); })} /></td>
                            {(["checks", "inputs", "outputs"] as const).map((f) => (
                              <td key={f}><textarea rows={3} title={t.lines} value={st[f].join("\n")} onChange={(e) => set((x) => { x[f] = lines(e.target.value); })} /></td>
                            ))}
                            <td><input value={st.user} onChange={(e) => set((x) => { x.user = e.target.value; })} /></td>
                            {current.cycles.map((c) => (
                              <td key={c}>
                                <select value={st.results[c] ?? ""} onChange={(e) => set((x) => { x.results[c] = e.target.value; })}>
                                  {Object.entries(RESULT_MARK).map(([v, m]) => <option key={v} value={v}>{m}</option>)}
                                </select>
                              </td>
                            ))}
                            <td>
                              <select value={st.status} onChange={(e) => set((x) => { x.status = e.target.value; })}>
                                {["open", "in-progress", "done", "on-hold"].map((v) => <option key={v} value={v}>{v}</option>)}
                              </select>
                            </td>
                            <td><textarea rows={2} value={st.followUp} onChange={(e) => set((x) => { x.followUp = e.target.value; })} /></td>
                            <td><button type="button" className="ghost icon" title={t.remove} onClick={() => edit((s) => { s.scenarios[si]!.steps.splice(ti, 1); })}><Icon name="trash" /></button></td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
                <button type="button" className="ghost" onClick={() => edit((s) => {
                  s.scenarios[si]!.steps.push({ id: `STEP-${String(s.scenarios[si]!.steps.length + 1).padStart(3, "0")}`, activity: "", system: "SAP", tcode: "", checks: [], inputs: [], outputs: [], user: "", status: "open", followUp: "", issue: "", results: {} });
                })}><Icon name="plus" /> {t.addStep}</button>
              </article>
            ))}
            <button type="button" className="ghost" onClick={() => edit((s) => {
              s.scenarios.push({ id: `${s.module}${String(s.scenarios.length + 1).padStart(2, "0")}`, theme: "", process: "", task: "", title: "", description: "", variant: "", owner: "", consultant: "", date: "", time: "", place: "", steps: [] });
            })}><Icon name="plus" /> {t.addScenario}</button>
          </>
        )}
      </section>
    </div>
  );
}

